import{_ as t,N as a,k as n,n as i}from"./chunks/framework.CP1bd6yz.js";const g=JSON.parse('{"title":"Release Notes for Order Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),o={name:"changelog.md"};function s(r,e,d,l,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="release-notes-for-order-lifecycle" tabindex="-1">Release Notes for Order Lifecycle <a class="header-anchor" href="#release-notes-for-order-lifecycle" aria-label="Permalink to “Release Notes for Order Lifecycle”">​</a></h1><h2 id="_1-0-0-beta-2-2026-07-03" tabindex="-1">1.0.0-beta.2 - 2026-07-03 <a class="header-anchor" href="#_1-0-0-beta-2-2026-07-03" aria-label="Permalink to “1.0.0-beta.2 - 2026-07-03”">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li>Fixed a stored XSS vulnerability where customer-supplied order data (addresses, coupon codes, SKUs) could end up rendered as unescaped HTML in the event log.</li><li>Hardened the plugin settings save process against unauthorized or unintended changes.</li><li>Added safeguards against AI prompt injection via customer-supplied order data.</li><li>Fixed a CSV injection vulnerability in event exports - a coupon code, SKU, or other order data starting with <code>=</code>, <code>+</code>, <code>-</code>, or <code>@</code> could be interpreted as a formula by Excel or Google Sheets when the export was opened.</li><li>CSV exports now require a POST request, closing off accidental large exports triggered by a crawled or bookmarked link.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li>AI-generated store insights now run in the background instead of holding up the page, and can be generated on demand with a Period selector and a Context/Notes field right there in the AI Insights widget - no need to visit a separate settings screen.</li><li>A new Performance guide, with recommended settings for high-traffic checkouts.</li><li>A new &quot;Per-Order Insights Style&quot; setting lets you choose how the order&#39;s AI analysis is presented: a structured view with a priority-action callout and labeled Action / Info / Good insight cards, or a plain narrative summary.</li><li>The order&#39;s Lifecycle timeline can now be filtered by event category (Cart, Line Items, Coupons, Customer, Address, Shipping, Payments, Order, Emails) and sorted oldest-first or newest-first.</li><li>Each timeline event now shows exactly what changed on the order since the previous event, with a &quot;View full snapshot&quot; link alongside it for the full raw detail underneath.</li><li>The Order Lifecycle Stats widget&#39;s &quot;Top Events&quot; list can now be turned off in the widget&#39;s settings, for stores that just want the stat grid.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Cut down database storage per logged event by dropping data that was never actually surfaced anywhere in the plugin.</li><li>Improved keyboard navigation, screen reader support, and colour contrast throughout the control panel.</li><li>The &quot;Top Events&quot; list now shows readable event names (e.g. &quot;Billing Address Set&quot;) instead of raw internal codes.</li><li>The AI Insights dashboard widget and page now share the same layout and controls, and the widget&#39;s separate settings screen is gone, since its one setting now lives directly on the widget.</li><li>Store-wide AI insight generation now has more headroom before Craft&#39;s queue considers it stuck, and a failed run now shows up as a retryable failure in the Queue Manager instead of disappearing silently.</li><li>The Lifecycle field&#39;s summary cards (Time to Convert, Checkout Duration, Cart Items, Customer) and the Started/Completed bar have a cleaner card layout.</li><li>Timeline events now show the time elapsed since the previous event, and only show the date when the timeline spans more than one day - every event still shows its own time.</li><li>Generating an order&#39;s AI analysis now shows a loading indicator with a short preview of what&#39;s coming, instead of just a disabled button.</li><li>&quot;Order Completed&quot; and &quot;Order Paid&quot; now use distinct icons in the timeline so the two milestones are easier to tell apart at a glance.</li><li>Status badges on timeline events (Payment Processed, Order Paid, Order Completed, Email Sent, Email Failed) no longer repeat what the event title already says - a badge now only appears when it adds real information, such as a failure or a specific status.</li><li>The Order Lifecycle Stats dashboard widget has a cleaner, single-surface layout, with stats grouped by what they measure (volume, conversion, timing) instead of a loose grid, and the order count moved into the widget&#39;s own title bar.</li><li>Line item change messages now show the product and variant name instead of the raw SKU.</li><li>Address change messages no longer repeat &quot;Shipping/Billing address set&quot; - just the address itself, since the event title already says what happened.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Shipping and billing country changes are now correctly recorded in the event log.</li><li>Fixed the AI Insights widget: results weren&#39;t loading after generation, saved insights showed up as raw text instead of formatted output, the button had lost its icon and label, and the spacing was off.</li><li>Fixed the &quot;Auto-Prune Logs&quot; setting not saving.</li><li>Improved CSV export performance on large date ranges.</li><li>Fixed several minor display and settings-saving bugs.</li><li>Fixed a bug where a Commerce order confirmation email could be sent to the customer more than once for the same order under load.</li><li>Timeline messages for coupon, address, customer, shipping-method, and line-item changes are now always generated from the correct prior state, even when Async Queue Logging is enabled and several events land for the same order in quick succession.</li><li>Fixed &quot;Billing Address Set&quot; and &quot;Shipping Address Set&quot; showing no changes when both addresses were saved together - each event now always shows its own correct field-by-field changes.</li><li>Fixed the sent email&#39;s name always showing blank in the event log.</li><li>Fixed &quot;Cart Created&quot;, &quot;Checkout Started&quot;, &quot;Coupon Applied&quot;, &quot;Coupon Removed&quot;, and &quot;Order Completed&quot; events not showing any description of what actually happened.</li><li>&quot;Payment Refunded&quot; events now show the amount refunded and the gateway it went through, instead of just the raw gateway/transaction-status field changes.</li><li>&quot;Payment Refunded&quot; events now show &quot;Amount Refunded&quot; and, if one was entered, the refund note in the changes table - the gateway and transaction status shown there previously belonged to the original charge, not the refund, and repeated the gateway already named in the event&#39;s message.</li><li>Fields that were never set no longer show up as a change from <code>null</code> to an empty value (e.g. &quot;Shipping Method: null → &#39;&#39;&quot;) in an event&#39;s changes table - only changes with a real value on at least one side are shown.</li></ul><h2 id="_1-0-0-beta-1-2026-06-05" tabindex="-1">1.0.0-beta.1 - 2026-06-05 <a class="header-anchor" href="#_1-0-0-beta-1-2026-06-05" aria-label="Permalink to “1.0.0-beta.1 - 2026-06-05”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial beta release</li></ul>',13)])])}const w=t(o,[["render",s]]);export{g as __pageData,w as default};
